"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[49831],{376:(e,i,t)=>{t.d(i,{Ji:()=>s,Nu:()=>n,O5:()=>r,Tw:()=>o,Zs:()=>l,mL:()=>c,yf:()=>a});let a=[{id:"locus-robotics-autonomous-amr",title:"Locus Robotics — Autonomous Mobile Robots for Warehouses",description:"Locus Robotics provides autonomous mobile robots (AMRs) that work alongside human workers in warehouses and distribution centers, picking, transporting, and sorting goods with minimal infrastructure changes. Their robots use AI-powered navigation, computer vision, and multi-robot coordination to increase pick productivity by 2-3x. Deployed in 300+ warehouses globally for retailers including DHL, Boots, and Material Bank.",category:"autonomous-warehouse-robotics",icon:"\uD83D\uDCE6",href:"/services/locus-robotics-autonomous-amr",industry:"Logistics & Warehousing",stage:"published",popular:!0,pricing:{basic:"Free (facility assessment)",pro:"$1,500/robot/month",enterprise:"Custom fleet pricing ($500K+/year)"},contactInfo:{website:"https://locusrobotics.com",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["Autonomous navigation: no facility modifications required — deploys in hours","Multi-robot coordination: 500+ robots working simultaneously without collisions","Human-robot collaboration: workers focus on picking, robots handle transport","Fleet management dashboard: real-time robot locations, productivity, and battery status","Integration with Manhattan, Blue Yonder, SAP, and other WMS platforms","Proven 2-3x productivity increase vs. manual cart-based picking"],benefits:["Solve warehouse labor shortage: deploy robots in days, not months","Workers achieve 300+ picks/hour vs. 80-100 with manual carts","Scalable: add robots during peak season, scale down during slow periods","Zero infrastructure: no QR codes, magnetic tape, or facility modifications needed","ROI achieved within 12 months through labor cost reduction and throughput gains"]}],o=[{id:"suno-ai-music-generation",title:"Suno AI — Text-to-Music Generation Platform",description:"Suno AI is a generative music platform that creates complete original songs — vocals, instruments, and production — from text prompts. Users describe a style, mood, or concept in natural language and Suno produces a broadcast-ready 2-4 minute track. With 10 million+ users, Suno is democratizing music production for content creators, game developers, advertisers, and independent artists who lack traditional music production resources.",category:"ai-music-generation",icon:"\uD83C\uDFB5",href:"/services/suno-ai-music-generation",industry:"Creative Technology & Entertainment",stage:"published",popular:!0,pricing:{basic:"Free (50 credits/day)",pro:"$10/month (2,500 credits)",enterprise:"$30/month (10,000 credits + commercial license)"},contactInfo:{website:"https://suno.com",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["Text-to-song: describe any genre, mood, or concept in natural language","Full vocal generation: AI sings lyrics in multiple languages and styles","Instrumental mode: generate music without vocals for background/corporate use","Commercial license: pro/enterprise plans include full commercial usage rights","Custom styles: upload reference tracks to match specific musical aesthetics","API access: integrate Suno generation into apps, games, and content platforms"],benefits:["Content creators produce royalty-free music in seconds, not weeks","Game developers generate dynamic soundtracks without hiring composers","Small businesses create professional jingles and brand music at zero cost","Independent artists prototype song ideas before studio recording","Multilingual: generate music with vocals in 20+ languages"]}],n=[{id:"onfido-ai-identity-verification",title:"Onfido (Plural) — AI-Powered Identity Verification",description:"Onfido uses AI to verify user identity through document analysis and facial biometrics, enabling banks, fintechs, and marketplaces to onboard customers remotely with bank-grade security. Their Real Identity Framework analyzes ID documents from 200+ countries, performs liveness detection, and cross-references against global watchlists — processing verifications in under 15 seconds with 99.9% accuracy.",category:"digital-identity-verification",icon:"\uD83E\uDEAA",href:"/services/onfido-ai-identity-verification",industry:"FinTech & Identity",stage:"published",popular:!0,pricing:{basic:"Pay-per-check ($1.50/verification)",pro:"$1,000/month + $1.00/check",enterprise:"Custom ($10K+/month)"},contactInfo:{website:"https://onfido.com",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["Document verification: 200+ countries, 4,000+ document types supported","Facial biometrics: liveness detection prevents spoofing with photos/videos","Address verification: utility bill analysis and geolocation cross-referencing","Watchlist screening: PEP, sanctions, and adverse media checks in real time","Orchestration dashboard: monitor verification funnel, drop-off rates, false positives","Compliance: KYC/AML compliant with GDPR, SOC 2, and ISO 27001 certification"],benefits:["Onboard customers in 15 seconds vs. days for manual verification","Reduce fraud losses by 95% with AI-powered document forgery detection","Increase conversion: 85% completion rate vs. 40% for manual processes","Global coverage: verify identities from any country without local offices","Regulator-approved: used by banks, neobanks, and fintechs in 50+ countries"]}],r=[{id:"felix-smart-city-iot-platform",title:"Felix Smart — AI-Powered Smart City IoT Management",description:"Felix Smart provides an AI platform for managing smart city infrastructure — street lighting, waste collection, parking, air quality, and traffic flow — through a unified IoT dashboard. Their platform connects 100,000+ city devices, uses predictive analytics to optimize operations, and reduces municipal energy costs by 30-60%. Deployed in cities across Europe, Asia, and North America.",category:"smart-city-iot",icon:"\uD83C\uDFD9️",href:"/services/felix-smart-city-iot-platform",industry:"Government & Municipal Technology",stage:"published",popular:!1,pricing:{basic:"Pilot (single district)",pro:"$50K/year (city-wide lighting)",enterprise:"Custom ($200K+/year full city deployment)"},contactInfo:{website:"https://felixsmart.com",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["Unified IoT dashboard: manage lighting, waste, parking, air quality, and traffic","Predictive maintenance: AI detects equipment failures before they occur","Smart lighting optimization: dim/brighten based on pedestrian and vehicle traffic","Waste collection routing: optimize pickup schedules based on bin fill-level sensors","Air quality monitoring: real-time pollution mapping with 50m resolution","Open API: integrate with existing city ERP, CRM, and citizen service platforms"],benefits:["Reduce municipal energy costs by 30-60% through intelligent lighting","Citizens enjoy cleaner streets: waste collected when bins are full, not on fixed schedule","Traffic congestion reduced 15% through adaptive signal timing","Carbon footprint reduction: measurable sustainability metrics for ESG reporting","Scalable: start with one district, expand to full city without platform changes"]}],s=[{id:"darktrace-ai-cyber-defense",title:"Darktrace — Self-Learning AI Cybersecurity Defense",description:'Darktrace uses self-learning AI to detect and respond to cyber threats in real time across cloud, email, endpoints, and industrial systems. Unlike rule-based security tools, Darktrace\'s AI learns the "pattern of life" for every user and device, identifying subtle anomalies that indicate ransomware, insider threats, or zero-day attacks — often detecting threats that other tools miss entirely.',category:"ai-powered-cybersecurity",icon:"\uD83D\uDEE1️",href:"/services/darktrace-ai-cyber-defense",industry:"Cybersecurity",stage:"published",popular:!0,pricing:{basic:"Free (30-day trial)",pro:"$50K/year (up to 500 assets)",enterprise:"Custom ($200K+/year for 10,000+ assets)"},contactInfo:{website:"https://darktrace.com",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["Self-learning AI: no rules or signatures — learns your environment autonomously","Real-time threat detection: identifies novel and zero-day attacks in seconds","Autonomous response: Antigena automatically contains threats without human intervention","Full coverage: cloud, email, endpoints, OT/ICS, and IoT from one platform","Explainable AI: plain-language threat reports for security team and auditors","MITRE ATT&CK mapping: all detections mapped to known adversary techniques"],benefits:["Detect threats that signature-based tools miss: novel malware, insider threats","Mean time to detect reduced from 200 days to seconds","Autonomous containment: stop ransomware spread in seconds, not hours","Reduce SOC alert fatigue by 90% — only actionable, high-fidelity alerts","Used by 6,500+ organizations including government agencies and critical infrastructure"]}],c=[{id:"plenty-vertical-farming-platform",title:"Plenty — AI-Powered Vertical Farming Platform",description:"Plenty operates AI-controlled vertical farms that grow leafy greens and strawberries indoors using 99% less water and 95% less land than conventional agriculture. Their proprietary platform uses computer vision, machine learning, and environmental controls to optimize every aspect of plant growth — light spectrum, nutrients, temperature, and airflow — producing 350x more food per acre than outdoor farms.",category:"vertical-farming",icon:"\uD83C\uDF31",href:"/services/plenty-vertical-farming-platform",industry:"AgriTech & Food Production",stage:"published",popular:!0,pricing:{basic:"Consumer (retail produce)",pro:"Farm partnership program",enterprise:"Turnkey farm solution ($50M+ per facility)"},contactInfo:{website:"https://plenty.ag",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["AI-optimized growing: computer vision monitors plant health in real time","350x more productive per acre than conventional farming","99% less water consumption vs. field agriculture","Zero pesticides: controlled environment eliminates pest pressure","Farm-to-store in 24 hours: facilities located near major population centers","Year-round production: immune to weather, seasons, and climate disruptions"],benefits:["Food security: grow locally even in arid, cold, or urban environments","Water conservation: critical for drought-prone regions and growing populations","Reduced supply chain: fresh produce within 24 hours of harvest","Climate resilient: production independent of weather, floods, or wildfires","Retail partnerships: Walmart, Whole Foods, and Albertsons stock Plenty produce"]}],l=[{id:"oura-ring-health-tracker",title:"Oura Ring — Clinical-Grade Health Tracking Wearable",description:"Oura Ring is a finger-worn health tracker that provides clinical-grade sleep analysis, heart rate variability (HRV), blood oxygen, body temperature, and activity tracking. With FDA-cleared features and partnerships with the US Department of Defense, Mayo Clinic, and 100+ research institutions, Oura has 2.5 million+ rings sold and is used for early illness detection, fertility tracking, and athletic performance optimization.",category:"wearable-health-tech",icon:"\uD83D\uDC8D",href:"/services/oura-ring-health-tracker",industry:"HealthTech & Wearables",stage:"published",popular:!0,pricing:{basic:"$299 (ring) + $6/month (membership)",pro:"$399 (Heritage)",enterprise:"Corporate wellness ($150/employee/year)"},contactInfo:{website:"https://ouraring.com",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["Sleep tracking: clinical-grade sleep stages, REM, deep sleep, and sleep efficiency","HRV monitoring: real-time autonomic nervous system balance tracking","Temperature sensing: detects fever onset and menstrual cycle phases","Activity tracking: steps, calories, training load, and recovery optimization","Readiness score: daily 0-100 score combining sleep, activity, and recovery","API integration: connect with Apple Health, Google Fit, Garmin, and EHR systems"],benefits:["Early illness detection: temperature trends identify COVID, flu before symptoms","Sleep optimization: users improve sleep quality by 20% within 30 days","Athletic performance: NBA, NFL, and Formula 1 teams use Oura for recovery","Fertility tracking: detect ovulation with 92% accuracy via temperature trends","Clinical validation: used in 100+ peer-reviewed research studies"]}]},9992:(e,i,t)=>{t.d(i,{PO:()=>r,eP:()=>s,fK:()=>a,k1:()=>n,v2:()=>o});let a=[{id:"hawk-eye-ai-video-analytics",title:"Hawk-Eye — AI-Powered Video Analytics for Sports & Security",description:"Hawk-Eye is a computer vision technology company that provides AI-powered video analysis for sports officiating, security, and entertainment. Their Smart Replay and Synchronized Multi-Angle Replay Technology (SMART) systems use 30+ high-speed cameras and deep learning to track ball trajectory, player movement, and event detection with millimeter accuracy. Used by FIFA, NFL, Premier League, and Wimbledon, Hawk-Eye processes over 100,000 decisions annually with 99.9% accuracy. Their security division provides real-time threat detection and crowd analytics for stadiums and public venues.",category:"ai-video-analytics",icon:"\uD83D\uDCF9",href:"/services/hawk-eye-ai-video-analytics",industry:"Sports Technology & Security",stage:"published",popular:!0,pricing:{basic:"Free (demo)",pro:"$50K/year (single venue)",enterprise:"Custom ($500K+/year multi-venue)"},contactInfo:{website:"https://hawkeyeinnovations.com",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["30+ high-speed camera array with sub-millimeter tracking accuracy","Real-time ball and player trajectory prediction using deep learning","Automated event detection: goals, fouls, line calls, and boundary decisions","Security mode: crowd density analysis, anomaly detection, and threat identification","Cloud-based replay center: instant multi-angle synchronized replays","API integration: embed analytics into broadcast, betting, and coaching platforms"],benefits:["Eliminate officiating errors with 99.9% accurate automated decisions","Reduce security response time by 80% with AI threat detection","Enhance fan experience with instant replay and data-driven insights","Generate new revenue through data licensing to broadcasters and betting operators","Trusted by FIFA, NFL, Premier League, and 20+ major sports leagues worldwide"]}],o=[{id:"elevenlabs-synthetic-voice-cloning",title:"ElevenLabs — AI Synthetic Voice Cloning & Text-to-Speech",description:"ElevenLabs is the leading AI voice technology platform that creates hyper-realistic synthetic voices from short audio samples. Their voice cloning technology captures vocal characteristics, accent, emotion, and speaking style to produce indistinguishable-from-human speech in 32 languages. With 1 million+ users and enterprise customers including The New York Times, Storytel, and Flo, ElevenLabs powers audiobook narration, podcast localization, video dubbing, and IVR replacement. Their Voice Library offers 10,000+ pre-built voices, while custom Voice Design creates unique brand voices from scratch.",category:"synthetic-voice-cloning",icon:"\uD83C\uDF99️",href:"/services/elevenlabs-synthetic-voice-cloning",industry:"Media, Entertainment & Voice AI",stage:"published",popular:!0,pricing:{basic:"Free (10K chars/month)",pro:"$5/month (30K chars)",enterprise:"$330/month (2M chars + voice cloning)"},contactInfo:{website:"https://elevenlabs.io",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["Voice cloning from 1-minute audio sample with 95% similarity to original voice","32 languages with native-sounding accents and natural prosody","Emotion and tone control: adjust happiness, sadness, anger, whispering, shouting","Voice Library: 10,000+ pre-built voices across ages, accents, and styles","Voice Design: create unique synthetic voices without any reference audio","API and SDK: real-time streaming TTS with <200ms latency for interactive applications"],benefits:["Produce audiobooks 10x faster without hiring voice actors","Localize video content into 32 languages with consistent brand voice","Replace expensive IVR systems with natural-sounding AI voice agents","Content creators produce professional narration without recording equipment","Used by 1 million+ users including major publishers and media companies"]}],n=[{id:"ironclad-ai-contract-lifecycle-management",title:"Ironclad — AI-Powered Contract Lifecycle Management",description:"Ironclad is an AI-powered contract lifecycle management (CLM) platform that automates the entire contract workflow from creation to execution to renewal. Their AI extracts key terms, flags risks, suggests alternative clauses, and tracks obligations across millions of contracts. Used by 2,500+ enterprises including L'Or\xe9al, Fitbit, and Cruise, Ironclad processes $1 trillion+ in contract value annually. Their AI Playbooks negotiate 80% of routine contracts without legal team involvement, reducing cycle time from weeks to hours.",category:"ai-contract-lifecycle",icon:"\uD83D\uDCCB",href:"/services/ironclad-ai-contract-lifecycle-management",industry:"Legal Technology & Enterprise SaaS",stage:"published",popular:!0,pricing:{basic:"Free (trial)",pro:"$45K/year (standard CLM)",enterprise:"Custom ($150K+/year with AI add-ons)"},contactInfo:{website:"https://ironcladapp.com",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["AI contract analysis: auto-extract 50+ key terms, dates, and obligations","AI Playbooks: negotiate routine contracts without legal team involvement","Risk scoring: flag non-standard clauses and suggest approved alternatives","Obligation tracking: automated reminders for renewals, payments, and deadlines","Workflow automation: routing, approvals, e-signature, and repository in one platform","Integration with Salesforce, DocuSign, SAP Ariba, and Microsoft 365"],benefits:["Reduce contract cycle time by 75% — from weeks to hours","Legal team focuses on strategic work: 80% of routine contracts auto-negotiated","Never miss a renewal or obligation with automated tracking and alerts","Standardize contract language across all business units","Process $1T+ in contract value with 2,500+ enterprise customers"]}],r=[{id:"waymo-autonomous-vehicle-telemetry",title:"Waymo — Autonomous Vehicle Telemetry & Fleet Intelligence",description:"Waymo, an Alphabet subsidiary, operates the world's largest commercial autonomous ride-hailing service with 700+ vehicles completing 150,000+ paid rides per week across San Francisco, Phoenix, Los Angeles, and Austin. Their telemetry platform processes 20+ TB of sensor data per vehicle per day from LiDAR, cameras, and radar, using AI to make real-time driving decisions. Waymo's simulation platform runs 20 billion+ virtual miles annually to validate safety scenarios. With 10+ years of real-world driving data, Waymo's AI has driven 20+ million autonomous miles on public roads with 85% fewer injury-causing crashes than human drivers.",category:"autonomous-vehicle-telemetry",icon:"\uD83D\uDE97",href:"/services/waymo-autonomous-vehicle-telemetry",industry:"Autonomous Vehicles & Transportation",stage:"published",popular:!0,pricing:{basic:"Free (ride-hailing per trip)",pro:"Fleet partnership program",enterprise:"Custom (OEM licensing)"},contactInfo:{website:"https://waymo.com",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["Multi-sensor fusion: LiDAR, 29 cameras, and 6 radar units per vehicle","Real-time telemetry: 20+ TB of sensor data processed per vehicle daily","AI driving policy: deep learning models trained on 20M+ real-world miles","Simulation platform: 20+ billion virtual miles for safety validation annually","Fleet management: real-time vehicle health, routing, and passenger matching","Safety reporting: 85% fewer injury-causing crashes vs. human driver baseline"],benefits:["Eliminate human error: 94% of crashes involve human mistakes","24/7 availability: autonomous fleets operate around the clock","Reduce transportation costs by 50% vs. private car ownership","Accessibility: provide mobility for elderly and disabled passengers","Proven at scale: 150,000+ paid rides per week across 4 major US cities"]}],s=[{id:"axe-deque-ai-accessibility-testing",title:"axe by Deque — AI-Powered Web Accessibility Testing",description:"axe by Deque Systems is the leading AI-powered accessibility testing platform that automatically detects WCAG 2.2, Section 508, and EN 301 549 compliance issues in web and mobile applications. Their AI engine uses computer vision and machine learning to identify 80%+ of accessibility issues that manual testing misses, including color contrast, missing alt text, keyboard navigation, and screen reader compatibility. With 1 million+ developers using axe tools and enterprise customers including Microsoft, Google, and the US federal government, Deque has tested over 10 billion web pages for accessibility compliance.",category:"ai-accessibility-testing",icon:"♿",href:"/services/axe-deque-ai-accessibility-testing",industry:"Accessibility & Compliance Technology",stage:"published",popular:!0,pricing:{basic:"Free (axe DevTools Community)",pro:"$40/month (axe DevTools Pro)",enterprise:"$50K/year (axe Monitor + automated scanning)"},contactInfo:{website:"https://deque.com/axe",email:"kleber@ziontechgroup.com",phone:"+1 302 464 0950"},features:["Automated WCAG 2.2, Section 508, and EN 301 549 compliance scanning","AI-powered issue detection: 80%+ of accessibility issues found automatically","Browser extension: test any webpage in seconds with axe DevTools","CI/CD integration: GitHub Actions, Jenkins, Azure DevOps, and CircleCI plugins","Intelligent guided testing: AI suggests manual tests for complex accessibility issues","Enterprise monitoring: continuous scanning of entire web properties for accessibility regressions"],benefits:["Avoid costly accessibility lawsuits: 4,000+ ADA web lawsuits filed in 2023","Reach 16% of the global population with disabilities — a $13T market","Automated testing finds issues 10x faster than manual accessibility audits","Meet legal requirements: WCAG 2.2 AA compliance for government and enterprise","Used by 1 million+ developers including Microsoft, Google, and US federal agencies"]}]}}]);